import * as React from "react";
import { Info, CircleCheck, TriangleAlert } from "lucide-react";
import { cn } from "@/lib/utils";
export function Alert({
  title,
  children,
  variant = "info",
  className,
}: {
  title: string;
  children?: React.ReactNode;
  variant?: "info" | "success" | "warning" | "destructive";
  className?: string;
}) {
  const Icon =
    variant === "success"
      ? CircleCheck
