import type {
  ColumnFiltersState,
  ColumnOrderState,
  ColumnPinningState,
  ColumnSizingState,
  PaginationState,
  SortingState,
  VisibilityState,
} from "@tanstack/react-table";

/** Serializable table state. Filtering, sorting and pagination belong to the data owner in external mode. */
export type DataTableQuery = {
  search: string;
  filters: ColumnFiltersState;
  sorting: SortingState;
  pagination: PaginationState;
};

/** Separate from DataTable's existing `columnVisibility` menu flag. */
export type DataTableColumnState = {
  visibility: VisibilityState;
  order: ColumnOrderState;
  sizing: ColumnSizingState;
  pinning: ColumnPinningState;
};

export type DataFilterScalar = string | number | boolean | null;
export type DataFilter =
  | { operator: "contains" | "startsWith"; value: string }
  | { operator: "equals" | "notEquals"; value: DataFilterScalar }
  | { operator: "in" | "notIn"; value: DataFilterScalar[] }
  | { operator: "gt" | "gte" | "lt" | "lte"; value: number }
  | { operator: "between"; value: [number | null, number | null] }
  | { operator: "dateBetween"; value: [string | null, string | null] }
  | { operator: "isEmpty" | "isNotEmpty" };

type JsonValue = DataFilterScalar | JsonValue[] | { [key: string]: JsonValue };

export type DataQueryNormalizationOptions = {
  pageSize?: number;
  maxPageSize?: number;
  columnIds?: readonly string[];
};

function record(value: unknown): Record<string, unknown> | undefined {
  if (
    !value ||
    typeof value !== "object" ||
    Array.isArray(value) ||
    (Object.getPrototypeOf(value) !== Object.prototype &&
      Object.getPrototypeOf(value) !== null)
  ) {
    return undefined;
  }
  return value as Record<string, unknown>;
}

function jsonValue(value: unknown, depth = 0): JsonValue | undefined {
  if (depth > 12) return undefined;
  if (
    value === null ||
    typeof value === "string" ||
    typeof value === "boolean"
  ) {
    return value;
  }
  if (typeof value === "number")
    return Number.isFinite(value) ? value : undefined;
  if (Array.isArray(value)) {
    const values = value.map((item) => jsonValue(item, depth + 1));
    return values.some((item) => item === undefined)
      ? undefined
      : (values as JsonValue[]);
  }
  const object = record(value);
  if (!object) return undefined;
  const entries = Object.keys(object)
    .sort()
    .map((key) => [key, jsonValue(object[key], depth + 1)] as const);
  return entries.some(([, item]) => item === undefined)
    ? undefined
    : (Object.fromEntries(entries) as { [key: string]: JsonValue });
}

function integer(
  value: unknown,
  fallback: number,
  minimum: number,
  maximum = Number.MAX_SAFE_INTEGER,
) {
  const number =
    typeof value === "number"
      ? value
      : typeof value === "string" && value.trim()
        ? Number(value)
        : NaN;
  return Number.isFinite(number)
    ? Math.min(maximum, Math.max(minimum, Math.trunc(number)))
    : fallback;
}

function scalar(value: unknown): value is DataFilterScalar {
  return (
    value === null ||
    typeof value === "string" ||
    typeof value === "boolean" ||
    (typeof value === "number" && Number.isFinite(value))
  );
}

function dateDay(value: unknown): number | undefined {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value))
    return undefined;
  const timestamp = Date.parse(`${value}T00:00:00.000Z`);
  return Number.isFinite(timestamp) &&
    new Date(timestamp).toISOString().slice(0, 10) === value
    ? timestamp
    : undefined;
}

export function isDataFilter(value: unknown): value is DataFilter {
  const filter = record(value);
  if (!filter) return false;
  switch (filter.operator) {
    case "contains":
    case "startsWith":
      return typeof filter.value === "string";
    case "equals":
    case "notEquals":
      return scalar(filter.value);
    case "in":
    case "notIn":
      return Array.isArray(filter.value) && filter.value.every(scalar);
    case "gt":
    case "gte":
    case "lt":
    case "lte":
      return typeof filter.value === "number" && Number.isFinite(filter.value);
    case "between":
      return (
        Array.isArray(filter.value) &&
        filter.value.length === 2 &&
        filter.value.every(
          (bound) =>
            bound === null ||
            (typeof bound === "number" && Number.isFinite(bound)),
        )
      );
    case "dateBetween":
      return (
        Array.isArray(filter.value) &&
        filter.value.length === 2 &&
        filter.value.every(
          (bound) => bound === null || dateDay(bound) !== undefined,
        )
      );
    case "isEmpty":
    case "isNotEmpty":
      return true;
    default:
      return false;
  }
}

function emptyFilter(value: unknown) {
  if (value === undefined || value === "") return true;
  if (!isDataFilter(value)) return Array.isArray(value) && value.length === 0;
  if (value.operator === "contains" || value.operator === "startsWith")
    return value.value === "";
  if (value.operator === "in" || value.operator === "notIn")
    return value.value.length === 0;
  if (value.operator === "between" || value.operator === "dateBetween") {
    return value.value.every((bound) => bound === null);
  }
  return false;
}

export function normalizeDataTableQuery(
  value: unknown = {},
  options: DataQueryNormalizationOptions = {},
): DataTableQuery {
  const input = record(value) ?? {};
  const allowed = options.columnIds ? new Set(options.columnIds) : undefined;
  const id = (value: unknown) =>
    typeof value === "string" &&
    value.trim() &&
    (!allowed || allowed.has(value))
      ? value
      : undefined;
  const filters = new Map<string, JsonValue>();
  for (const item of Array.isArray(input.filters) ? input.filters : []) {
    const filter = record(item),
      columnId = id(filter?.id);
    if (!filter || !columnId) continue;
    const normalized = jsonValue(filter.value);
    if (
      emptyFilter(normalized) ||
      (record(normalized)?.operator !== undefined && !isDataFilter(normalized))
    ) {
      filters.delete(columnId);
    } else if (normalized !== undefined) {
      filters.set(columnId, normalized);
    }
  }
  const sorting = new Map<string, { id: string; desc: boolean }>();
  for (const item of Array.isArray(input.sorting) ? input.sorting : []) {
    const sort = record(item),
      columnId = id(sort?.id);
    if (columnId)
      sorting.set(columnId, { id: columnId, desc: sort?.desc === true });
  }
  const pagination = record(input.pagination) ?? {};
  const maximum = integer(options.maxPageSize, Number.MAX_SAFE_INTEGER, 1);
  const fallbackSize = integer(options.pageSize, 5, 1, maximum);
  return {
    // Preserve spaces while typing. Trimming controlled input state loses word separators.
    search: typeof input.search === "string" ? input.search : "",
    filters: [...filters]
      .sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0))
      .map(([id, value]) => ({ id, value })),
    // Multi-sort precedence is ordered, unlike AND filters.
    sorting: [...sorting.values()],
    pagination: {
      pageIndex: integer(pagination.pageIndex, 0, 0),
      pageSize: integer(pagination.pageSize, fallbackSize, 1, maximum),
    },
  };
}

export function serializeDataTableQuery(query: DataTableQuery): string {
  return JSON.stringify({ version: 1, query: normalizeDataTableQuery(query) });
}

export function parseDataTableQuery(
  source: string | null | undefined,
  options: DataQueryNormalizationOptions = {},
): DataTableQuery {
  if (!source) return normalizeDataTableQuery({}, options);
  try {
    const input = record(JSON.parse(source));
    return input?.version === 1
      ? normalizeDataTableQuery(input.query, options)
      : normalizeDataTableQuery({}, options);
  } catch {
    return normalizeDataTableQuery({}, options);
  }
}

export function normalizeDataTableColumnState(
  value: Partial<DataTableColumnState> | unknown = {},
): DataTableColumnState {
  const input = record(value) ?? {};
  const visibility = record(input.visibility) ?? {},
    sizing = record(input.sizing) ?? {};
  const ids = (value: unknown) => [
    ...new Set(
      (Array.isArray(value) ? value : []).filter(
        (id): id is string => typeof id === "string" && id.trim().length > 0,
      ),
    ),
  ];
  const pinning = record(input.pinning) ?? {},
    left = ids(pinning.left);
  return {
    visibility: Object.fromEntries(
      Object.entries(visibility)
        .filter(([, visible]) => typeof visible === "boolean")
        .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)),
    ) as VisibilityState,
    order: ids(input.order),
    sizing: Object.fromEntries(
      Object.entries(sizing)
        .filter(
          ([, size]) =>
            typeof size === "number" && Number.isFinite(size) && size > 0,
        )
        .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)),
    ) as ColumnSizingState,
    pinning: {
      left,
      right: ids(pinning.right).filter((id) => !left.includes(id)),
    },
  };
}

function fold(value: unknown) {
  return String(value ?? "")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
}

function numeric(value: unknown): number | undefined {
  if (typeof value === "number")
    return Number.isFinite(value) ? value : undefined;
  if (typeof value !== "string" || !value.trim()) return undefined;
  const number = Number(value);
  return Number.isFinite(number) ? number : undefined;
}

/** AND across columns; `in` is OR within one field. No implicit conversion of empty cells to zero. */
export function matchesDataFilter(value: unknown, filter: unknown): boolean {
  if (emptyFilter(filter)) return true;
  if (!isDataFilter(filter)) {
    if (Array.isArray(filter))
      return filter.some((item) => Object.is(item, value));
    return typeof filter === "string"
      ? fold(value).includes(fold(filter))
      : Object.is(value, filter);
  }
  switch (filter.operator) {
    case "contains":
      return fold(value).includes(fold(filter.value));
    case "startsWith":
      return fold(value).startsWith(fold(filter.value));
    case "equals":
      return Object.is(value, filter.value);
    case "notEquals":
      return !Object.is(value, filter.value);
    case "in":
      return filter.value.some((item) => Object.is(item, value));
    case "notIn":
      return !filter.value.some((item) => Object.is(item, value));
    case "isEmpty":
      return (
        value === null ||
        value === undefined ||
        value === "" ||
        (Array.isArray(value) && value.length === 0)
      );
    case "isNotEmpty":
      return (
        value !== null &&
        value !== undefined &&
        value !== "" &&
        (!Array.isArray(value) || value.length > 0)
      );
    case "dateBetween": {
      const timestamp =
        value instanceof Date
          ? value.getTime()
          : typeof value === "string"
            ? value.length === 10
              ? (dateDay(value) ?? NaN)
              : Date.parse(value)
            : NaN;
      const [from, to] = filter.value;
      return (
        Number.isFinite(timestamp) &&
        (from === null || timestamp >= dateDay(from)!) &&
        (to === null || timestamp < dateDay(to)! + 86_400_000)
      );
    }
    default: {
      const number = numeric(value);
      if (number === undefined) return false;
      if (filter.operator === "between") {
        const [from, to] = filter.value;
        return (
          (from === null || number >= from) && (to === null || number <= to)
        );
      }
      if (filter.operator === "gt") return number > filter.value;
      if (filter.operator === "gte") return number >= filter.value;
      if (filter.operator === "lt") return number < filter.value;
      return number <= filter.value;
    }
  }
}

export function filterDataRows<T>(
  rows: readonly T[],
  filters: ColumnFiltersState,
  getValue: (row: T, columnId: string) => unknown,
): T[] {
  return rows.filter((row) =>
    filters.every((filter) =>
      matchesDataFilter(getValue(row, filter.id), filter.value),
    ),
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
export function downloadText(
  filename: string,
  text: string,
  type = "text/plain",
) {
  const url = URL.createObjectURL(new Blob([text], { type }));
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
export function csv(rows: Record<string, unknown>[]) {
  if (!rows.length) return "";
  const keys = Object.keys(rows[0]);
  const escape = (value: unknown) => {
    const raw = String(value ?? "");
    const safe = /^[=+@\t\r-]/.test(raw) ? `'${raw}` : raw;
    return `"${safe.replaceAll('"', '""')}"`;
  };
  return [
    keys.map(escape).join(","),
    ...rows.map((row) => keys.map((k) => escape(row[k])).join(",")),
  ].join("\r\n");
}

/*
 * Aureform effects. Import after the generated tokens.css in globals.css.
 * Component-layer rules allow Tailwind utilities to override decoration.
 * Shadow composition retains Tailwind 4 focus rings.
 */
@layer components {
  .af-surface-gradient {
    background-color: var(--surface);
    background-image: var(--af-gradient-surface);
  }

  .af-hero-gradient {
    background-color: var(--background);
    background-image: var(--af-gradient-hero);
  }

  .af-shadow-soft {
    --tw-shadow: var(--af-shadow-soft);
  }

  .af-shadow-elevated {
    --tw-shadow: var(--af-hover-shadow, var(--af-shadow-elevated));
  }

  .af-shadow-floating {
    --tw-shadow: var(--af-shadow-floating);
  }

  .af-shadow-soft,
  .af-shadow-elevated,
  .af-shadow-floating,
  .af-hover-card,
  .af-button {
    box-shadow:
      var(--tw-inset-shadow, 0 0 #0000), var(--tw-inset-ring-shadow, 0 0 #0000),
      var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000),
      var(--tw-shadow, 0 0 #0000);
  }

  .af-button {
    transition:
      background-color var(--af-motion-fast) var(--af-motion-easing),
      border-color var(--af-motion-fast) var(--af-motion-easing),
      color var(--af-motion-fast) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing);
  }

  .af-button-primary,
  .af-button-outline,
  .af-button-surface,
  .af-button-destructive {
    background-image: var(--af-gradient-control);
  }

  .af-button-primary,
  .af-button-surface,
  .af-button-destructive {
    --tw-shadow: var(--af-shadow-soft);
  }

  .af-hover-card {
    transition:
      background-color var(--af-motion-fast) var(--af-motion-easing),
      border-color var(--af-motion-fast) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing),
      transform var(--af-motion-hover) var(--af-motion-easing);
  }

  .af-hover-link {
    color: var(--primary);
    text-decoration-line: underline;
    text-decoration-color: color-mix(in srgb, var(--primary) 45%, transparent);
    text-decoration-thickness: 1px;
    text-underline-offset: 0.22em;
    transition:
      color var(--af-motion-fast) var(--af-motion-easing),
      text-decoration-color var(--af-motion-fast) var(--af-motion-easing);
  }

  .af-hover-link:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):focus-visible {
    color: var(--primary-hover);
    text-decoration-color: currentColor;
    text-decoration-thickness: 2px;
    outline: 2px solid var(--ring);
    outline-offset: 3px;
  }

  @media (hover: hover) and (pointer: fine) {
    .af-button-outline:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      --tw-shadow: var(--af-shadow-soft);
    }

    .af-hover-link:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      color: var(--primary-hover);
      text-decoration-color: currentColor;
      text-decoration-thickness: 2px;
    }
  }

  .af-button:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):active {
    --tw-shadow: 0 0 #0000;
  }

  .af-button:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ),
  .af-hover-card:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ),
  .af-hover-link:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ) {
    cursor: default;
    pointer-events: none;
    animation: none;
    transition: none;
    transform: none;
    translate: none;
  }

  .af-button:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ) {
    --tw-shadow: 0 0 #0000;
    background-image: none;
  }
}

/* Interactive state colors must take precedence over a base bg-surface utility. */
@layer utilities {
  .af-hover-card:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):focus-visible {
    --tw-shadow: var(--af-shadow-elevated);
    background-color: var(--af-shade-card);
    outline: 2px solid var(--ring);
    outline-offset: 3px;
    transform: translateY(var(--af-motion-lift));
  }

  @media (hover: hover) and (pointer: fine) {
    .af-hover-card:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      --tw-shadow: var(--af-hover-shadow, var(--af-shadow-elevated));
      background-color: var(--af-shade-card);
      transform: translateY(var(--af-motion-lift));
    }
  }
}

@layer components {
  .af-appearance-scope {
    color: var(--foreground);
    background-color: var(--background);
    font-family: var(--font-manrope, "Manrope"), system-ui, sans-serif;
  }

  .af-gradient-text {
    color: var(--primary);
    background-image: var(--af-gradient-text);
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }

  .af-gradient-border {
    border-color: color-mix(in srgb, var(--primary) 40%, var(--border));
    box-shadow: inset 0 1px 0 color-mix(in srgb, var(--primary) 18%, transparent);
  }

  .af-card {
    --tw-shadow: var(--af-card-shadow, var(--af-shadow-soft));
    background-color: var(--af-card-background, var(--surface));
    background-image: var(--af-card-image, none);
    -webkit-backdrop-filter: var(--af-card-blur, none);
    backdrop-filter: var(--af-card-blur, none);
    border-radius: var(--af-radius, 16px);
    transition:
      border-color var(--af-motion-hover) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing),
      background-color var(--af-motion-fast) var(--af-motion-easing);
  }

  .af-card-flat {
    --af-card-background: var(--surface);
    --af-card-image: none;
    --af-card-shadow: 0 0 #0000;
    --af-card-blur: none;
  }
  .af-card-elevated {
    --af-card-background: var(--surface);
    --af-card-image: none;
    --af-card-shadow: var(--af-shadow-elevated);
    --af-card-blur: none;
  }
  .af-card-glass {
    --af-card-background: var(--af-glass-background);
    --af-card-image: linear-gradient(130deg, color-mix(in srgb, var(--primary) 8%, transparent), transparent 65%);
    --af-card-shadow: var(--af-shadow-soft);
    --af-card-blur: blur(var(--af-glass-blur));
    border-color: color-mix(in srgb, var(--primary) 30%, var(--border));
  }
  .af-card-gradient {
    --af-card-background: var(--surface);
    --af-card-image: linear-gradient(135deg, var(--surface) 25%, color-mix(in srgb, var(--af-color-primary) 20%, var(--surface)));
    --af-card-shadow: var(--af-shadow-elevated);
    --af-card-blur: none;
    border-color: color-mix(in srgb, var(--primary) 30%, var(--border));
  }

  .af-control-solid { background-image: none; }
  .af-control-gradient {
    background-color: var(--primary);
    background-image: var(--af-gradient-primary);
    color: var(--primary-foreground);
    --tw-shadow: var(--af-shadow-soft);
  }
  .af-control-gradient:hover:not(:disabled,[data-disabled]) {
    --tw-shadow: var(--af-glow);
  }
  .af-control-soft {
    background-color: var(--accent);
    background-image: none;
    color: var(--accent-foreground);
    border: 1px solid color-mix(in srgb, var(--primary) 24%, var(--border));
  }
  .af-control-outline {
    background-color: var(--surface);
    background-image: none;
    border: 1px solid color-mix(in srgb, var(--primary) 45%, var(--border));
    color: var(--foreground);
    --tw-shadow: 0 0 #0000;
  }
  .af-control-glass {
    background-color: var(--af-glass-background);
    background-image: linear-gradient(120deg, color-mix(in srgb, var(--primary) 10%, transparent), transparent);
    backdrop-filter: blur(var(--af-glass-blur));
    border: 1px solid color-mix(in srgb, var(--primary) 45%, var(--border));
    color: var(--foreground);
  }

  .af-badge-solid, .af-badge-gradient {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  .af-badge-gradient { background-image: var(--af-gradient-primary); }
  .af-badge-soft { background-color: var(--accent); color: var(--accent-foreground); }
  .af-badge-outline { background-color: transparent; color: var(--foreground); border: 1px solid var(--border); }
  .af-badge-glass { background-color: var(--af-glass-background); color: var(--foreground); border: 1px solid var(--border); backdrop-filter: blur(12px); }

  .af-button-destructive[data-appearance] {
    color: var(--destructive-foreground);
    background-color: var(--destructive);
    background-image: none;
    border-color: color-mix(in srgb, var(--destructive-foreground) 45%, var(--border));
  }
  .af-button[data-disabled], .af-button:disabled {
    background-image: none;
    backdrop-filter: none;
  }

  .af-input, .af-textarea {
    border-color: color-mix(in srgb, var(--muted-foreground) 48%, var(--surface));
  }
}

[data-motion-level="off"] :where(.af-button,.af-hover-card,.af-hover-link,.af-card),
[data-motion-level="off"] :where(.af-button,.af-hover-card,.af-hover-link,.af-card)::before,
[data-motion-level="off"] :where(.af-button,.af-hover-card,.af-hover-link,.af-card)::after {
  animation: none !important;
  transition: none !important;
  transform: none !important;
}

@media (prefers-reduced-motion: reduce) {
  .af-button,
  .af-button::before,
  .af-button::after,
  .af-button[aria-busy="true"] > svg,
  .af-hover-card,
  .af-hover-card::before,
  .af-hover-card::after,
  .af-hover-link,
  .af-hover-link::before,
  .af-hover-link::after {
    animation: none !important;
    transition: none !important;
    transform: none !important;
    translate: none !important;
  }
}
